/** 운영 환경에서 사용하는 S3 호환 Object Storage 구현입니다. */
package com.dandimate.durooduroo.storage;
import java.net.URI; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component; import org.springframework.web.multipart.MultipartFile; import software.amazon.awssdk.core.sync.RequestBody; import software.amazon.awssdk.regions.Region; import software.amazon.awssdk.services.s3.S3Client; import software.amazon.awssdk.services.s3.model.*;
@Component @ConditionalOnProperty(name="storage.type",havingValue="s3") public class S3ObjectStorage implements ObjectStorage {private final S3Client client;private final String bucket;public S3ObjectStorage(@Value("${storage.aws-region:ap-northeast-2}") String region,@Value("${storage.aws-bucket}") String bucket,@Value("${storage.aws-endpoint:}") String endpoint){var builder=S3Client.builder().region(Region.of(region));if(!endpoint.isBlank())builder.endpointOverride(URI.create(endpoint)).forcePathStyle(true);this.client=builder.build();this.bucket=bucket;}public String put(String key,MultipartFile file)throws Exception{client.putObject(PutObjectRequest.builder().bucket(bucket).key(key).contentType(file.getContentType()).build(),RequestBody.fromBytes(file.getBytes()));return "s3://"+bucket+"/"+key;}public void delete(String key){client.deleteObject(DeleteObjectRequest.builder().bucket(bucket).key(key).build());}}
